            for component_id, solver in SOLVERS.items()}

from itertools import product
import heapq
from collections import Counter


def _dependency_solver(data, preference, name_order):
    packages = data["packages"]
    names = sorted(packages, reverse=(name_order == "descending"))
    rows = {name: {row["version"]: row for row in versions}
            for name, versions in packages.items()}
    features = set(data.get("features", []))
    roots = data["roots"]
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = [[-1] + list(rows[name]) for name in names]
    best_vector = None
    best_versions = None

    for values in product(*choices):
        selected = dict(zip(names, values))
        if any(selected.get(name, -1) < bounds[0] or
               selected.get(name, -1) > bounds[1]
               for name, bounds in roots.items()):
            continue
        if any(selected[name] != -1 and
               (selected[name] in blocked.get(name, []) or
                (name in pins and selected[name] != pins[name]))
               for name in names):
            continue
        if any(name in pins and selected[name] == -1 for name in roots):
            continue

        closure = set(roots)
        edges = {}
        pending = list(roots)
        valid = True
        while pending and valid:
            name = pending.pop()
            version = selected.get(name, -1)
            row = rows.get(name, {}).get(version)
            if row is None:
                valid = False
                break
            active = [dep for dep in row.get("deps", [])
                      if not dep.get("feature") or dep.get("feature") in features]
            edges[name] = []
            for dep in active:
                child = dep["name"]
                child_version = selected.get(child, -1)
                if child_version < dep["min"] or child_version > dep["max"]:
                    valid = False
                    break
                edges[name].append(child)
                if child not in closure:
                    closure.add(child)
                    pending.append(child)
        if not valid or any(selected[name] == -1 for name in closure):
            continue
        if any(selected[name] != -1 and name not in closure for name in names):
            continue

        finished, active_path = set(), set()
        def visit(name):
            if name in active_path:
                return False
            if name in finished:
                return True
            active_path.add(name)
            for child in edges.get(name, []):
                if not visit(child):
                    return False
            active_path.remove(name)
            finished.add(name)
            return True
        if not all(visit(name) for name in closure):
            continue

        vector = tuple(selected[name] for name in names)
        if best_vector is None or ((vector > best_vector) if preference == "maximum"
                                   else (vector < best_vector)):
            best_vector = vector
            best_versions = {name: selected[name] for name in names
                             if selected[name] != -1}

    if best_versions is None:
        return {"error": "unsatisfiable"}
    return {"versions": best_versions}


def _build_dependency(preference, order):
    return lambda data: _dependency_solver(data, preference, order)


def _component_06(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    def rounded(n, d):
        return (n + d // 2) // d if mode == "half_up" else n // d

    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000)
        tax = rounded(raw * event.get("tax_bp", 0), 10000)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _component_07(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best = None
    n = len(jobs)
    for mask in range(1 << n):
        if mask.bit_count() != k:
            continue
        chosen = [jobs[i] for i in range(n) if mask >> i & 1]
        ids = {job["id"] for job in chosen}
        if ids & blocked or not mandatory.issubset(ids):
            continue
        counts = Counter(job["group"] for job in chosen)
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        events = []
        for job in chosen:
            events.append((job["start"], 1))
            events.append((job["end"], -1))
        active = 0
        valid = True
        for _, delta in sorted(events, key=lambda item: (item[0], item[1])):
            active += delta
            if active > 2:
                valid = False
                break
        if not valid:
            continue
        for group in {job["group"] for job in chosen} | set(quotas):
            low, high = quotas.get(group, (0, k))
            if not low <= counts.get(group, 0) <= high:
                valid = False
                break
        if not valid:
            continue
        ids_sorted = tuple(sorted(ids))
        value = sum(job["value"] for job in chosen)
        candidate = (value, ids_sorted)
        if best is None or candidate > best:
            best = candidate
    if best is None:
        return {"error": "impossible"}
    return {"selected": list(best[1]), "value": best[0]}


def _component_08(data):
    required = data.get("required", [])
    bit_for = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    initial_mask = bit_for.get(start_node, 0)
    coupons = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    state = (start_node, initial_mask, 0)
    dist = {state: start}
    queue = [(start, start_node, initial_mask, 0)]
    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if dist.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < coupons:
                options.append((max(1, edge["duration"] - edge.get("discount", 0)), used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit_for.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if arrival < dist.get(next_state, float("inf")):
                    dist[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


SOLVERS = {
    "component_01": _build_dependency("maximum", "descending"),
    "component_02": _build_dependency("minimum", "descending"),
    "component_03": _build_dependency("maximum", "ascending"),
    "component_04": _build_dependency("minimum", "ascending"),
    "component_05": _build_dependency("maximum", "descending"),
    "component_06": _component_06,
    "component_07": _component_07,
    "component_08": _component_08,
}
